{
["trigger"] = {
["type"] = "custom",
["events"] = "ENCOUNTER_START, UNIT_SPELL_CAST_SUCCEEDED:boss, LIQUID_CUSTOM_EVENT",
["custom_type"] = "stateupdate",
["check"] = "event",
["debuffType"] = "HELPFUL",
["custom"] = "function(allstates, event, ...)\n    if event == \"LIQUID_CUSTOM_EVENT\" then\n        local id, encounterStart = ...\n        \n        if id ~= aura_env.id then return end\n        if encounterStart ~= aura_env.encounterStart then return end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 5,\n            expirationTime = GetTime() + 5,\n            autoHide = true\n        }\n        \n        return true\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not aura_env.active then return end\n        if not castGUID then return end\n        \n        if spellID == 442530 then -- Bloodcurdle\n            C_Timer.After(11, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n            C_Timer.After(43, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n            C_Timer.After(70, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n            C_Timer.After(102, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        local _, _, difficultyID = ...\n        \n        aura_env.active = false\n        aura_env.encounterStart = GetTime()\n        \n        if difficultyID == 16 then return end\n        \n        if (C_AddOns.IsAddOnLoaded(\"ExRT\") or C_AddOns.IsAddOnLoaded(\"MRT\")) and _G.VExRT.Note.Text1 then\n            for line in _G.VExRT.Note.Text1:gmatch(\"[^\\r\\n]+\") do\n                if strtrim(line) == \"simulate\" then\n                    aura_env.active = true\n                    \n                    C_Timer.After(11, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n                    C_Timer.After(43, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n                    C_Timer.After(70, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n                    C_Timer.After(102, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n                    \n                    return\n                end\n            end\n        end\n    end\nend",
["unit"] = "player",
},
