{
["outline"] = "OUTLINE",
["wagoID"] = "p5gVWr4D_",
["authorOptions"] = {
},
["displayText"] = "%c",
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    if not aura_env.state.count then return end\n    \n    if not aura_env.last or aura_env.last < GetTime() - 1 then\n        aura_env.last = GetTime()\n        \n        SendChatMessage(aura_env.state.count)\n    end\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "update",
["url"] = "https://wago.io/p5gVWr4D_/242",
["actions"] = {
