["customSort"] = "function(a, b)\n    if a.dataIndex ~= b.dataIndex then\n        return a.dataIndex <= b.dataIndex\n    else\n        if not (a.region and a.region.state) then return false end\n        if not (b.region and b.region.state) then return true end\n        \n        local stateA = a.region.state\n        local stateB = b.region.state\n        \n        if stateA.index ~= stateB.index then\n            return stateA.index < stateB.index\n        elseif stateA.stacks ~= stateB.stacks then -- Sort by stacks\n            return (stateA.stacks or 0) > (stateB.stacks or 0)\n        elseif stateA.role ~= stateB.role then -- Sort by role\n            return (stateA.role or 0) > (stateB.role or 0)\n        elseif stateA.unit ~= stateB.unit then\n            if not stateA.unit then return false end\n            if not stateB.unit then return true end\n            \n            local classA = UnitClassBase(stateA.unit)\n            local classB = UnitClassBase(stateB.unit)\n            \n            if classA ~= classB then -- Sort by class\n                return classA < classB\n            else\n                local nameA = UnitName(stateA.unit)\n                local nameB = UnitName(stateB.unit)\n                \n                if nameA ~= nameB then -- Sort by name\n                    return nameA < nameB\n                end\n            end\n        elseif stateA.GUID ~= stateB.GUID then -- Sort by GUID\n            return (stateA.GUID or 0) < (stateB.GUID or 0)\n        else -- Sort by expiration time\n            return (a.region.state.expirationTime or 0) > (b.region.state.expirationTime or 0)\n        end\n    end\nend",
