["wagoID"] = "p5gVWr4D_",
["parent"] = "The Silken Court - Lists",
["adjustedMax"] = "",
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        local name = LiquidAPI and LiquidAPI:GetName(\"player\") or UnitName(\"player\")\n        \n        local _, randomClass1 = GetClassInfo(math.random(13))\n        local _, randomClass2 = GetClassInfo(math.random(13))\n        \n        local colorStr1 = RAID_CLASS_COLORS[randomClass1].colorStr\n        local colorStr2 = RAID_CLASS_COLORS[randomClass2].colorStr\n        \n        local coloredName1 = string.format(\"|c%s%s|r\", colorStr1, name)\n        local coloredName2 = string.format(\"|c%s%s|r\", colorStr2, name)\n        \n        return coloredName1, coloredName2\n    end\n    \n    local name1 = WA_ClassColorName(aura_env.state.unit1)\n    local name2 = WA_ClassColorName(aura_env.state.unit2)\n    \n    -- Set nicknames (if available)\n    if aura_env.state.unit1 then\n        local nickname = LiquidAPI and LiquidAPI:GetName(aura_env.state.unit1)\n        \n        if nickname then\n            local classFileName = UnitClassBase(aura_env.state.unit1)\n            local colorStr = RAID_CLASS_COLORS[classFileName].colorStr\n            \n            name1 = string.format(\"|c%s%s|r\", colorStr, nickname)\n        end\n    end\n    \n    if aura_env.state.unit2 then\n        local nickname = LiquidAPI and LiquidAPI:GetName(aura_env.state.unit2)\n        \n        if nickname then\n            local classFileName = UnitClassBase(aura_env.state.unit2)\n            local colorStr = RAID_CLASS_COLORS[classFileName].colorStr\n            \n            name2 = string.format(\"|c%s%s|r\", colorStr, nickname)\n        end\n    end\n    \n    return name1, name2\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
