["customText"] = "function()\n    local unit = aura_env.state and aura_env.state.unitCaster or WeakAuras.IsOptionsOpen() and \"player\"\n    \n    if unit then\n        local nickname = LiquidAPI and LiquidAPI:GetName(unit)\n        \n        if nickname then\n            local classFileName = UnitClassBase(unit)\n            local colorStr = RAID_CLASS_COLORS[classFileName].colorStr\n            \n            return string.format(\"|c%s%s|r\", colorStr, nickname)\n        else\n            return WA_ClassColorName(unit)\n        end\n    end\nend",
