{
["outline"] = "OUTLINE",
["wagoID"] = "p5gVWr4D_",
["parent"] = "The Silken Court - Miscellaneous",
["displayText"] = "%c",
["customText"] = "function()\n    local c = aura_env.config.colors\n    \n    if c == 1 then\n        if aura_env.states[2] and aura_env.states[2].show then\n            return string.format(\"|cff2b43e0%d|r\", aura_env.state.blue)\n        elseif aura_env.states[3] and aura_env.states[3].show then\n            return string.format(\"|cfff51d2c%d|r\", aura_env.state.red)\n        end\n    elseif c == 2 then\n        return string.format(\"|cfff51d2c%d|r / |cff2b43e0%d|r\", aura_env.state.red, aura_env.state.blue)\n    end\nend",
["shadowYOffset"] = -1,
["anchorPoint"] = "TOP",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
