["custom"] = "aura_env.assignments = {\n    [1] = {\n        \"Back {rt2}\",\n        \"Front left {rt2}\",\n        \"Front right {rt2}\"\n    },\n    [2] = {\n        \"Gate/spread\",\n        \"Gate/spread\",\n        \"Gate/spread\"\n    },\n    [3] = {\n        \"Back {rt3}\",\n        \"Front left {rt3}\",\n        \"Front right {rt3}\"\n    },\n}\n\naura_env.tts = {\n    [1] = {\n        \"back\",\n        \"front left\",\n        \"front right\"\n    },\n    [3] = {\n        \"back\",\n        \"front left\",\n        \"front right\"\n    },\n}\n\naura_env.chatMessage = {\n    [1] = {\n        \"Back\",\n        \"Front left\",\n        \"Front right\"\n    },\n    [3] = {\n        \"Back\",\n        \"Front left\",\n        \"Front right\"\n    },\n}",
